1	import { ErrorResponse, UserManager, WebStorageStateStore, type User } from 'oidc-client-ts';
2	
3	import { authConfig, authMode } from './config';
4	
5	// OAuth error codes from a failed silent renew that genuinely need the user back
6	// at the IdP (expired session / dead refresh token / fresh consent or MFA) — as
7	// opposed to a transient network error, which must NOT trigger a redirect (#168).
8	const INTERACTION_REQUIRED_ERRORS = new Set([
9	  'login_required',
10	  'interaction_required',
11	  'consent_required',
12	  'account_selection_required',
13	  'invalid_grant',
14	]);
15	
16	/**
17	 * Generic OIDC auth client (ADR 0028 / #504) — replaces the Azure-specific MSAL
18	 * client. Any standards-compliant IdP works: Azure AD, Cognito, GCP Identity
19	 * Platform, Keycloak, or a local dev OIDC — the provider is just the injected
20	 * `authority`. Authorization-code + PKCE (oidc-client-ts default), refresh-token
21	 * silent renew (offline_access), session-storage cache (matches the old MSAL
22	 * choice so a tab reload keeps the session but a closed tab drops it).
23	 */
24	
25	let _mgr: UserManager | null = null;
26	
27	/**
28	 * The UserManager singleton in real auth mode; null in dev_bypass / unconfigured.
29	 * Caller awaits nothing to construct it — oidc-client-ts fetches the IdP metadata
30	 * lazily on first sign-in/callback.
31	 */
32	export function getUserManager(): UserManager | null {
33	  if (authMode !== 'real') return null;
34	  if (_mgr) return _mgr;
35	
36	  const { authority, clientId, apiScope, scope: scopeOverride } = authConfig;
37	  if (!authority || !clientId) {
38	    // authMode='real' guarantees both are set; defensive guard satisfies the type checker.
39	    throw new Error(
40	      'Real auth mode requires an authority + clientId (DATAQ_AUTH_* runtime config)',
41	    );
42	  }
43	
44	  // openid/profile/email → id token; offline_access → refresh token for silent
45	  // renew; apiScope (when set) makes the access token audience the DataQ API.
46	  // DATAQ_AUTH_SCOPE replaces the whole string for providers with a different
47	  // scope vocabulary — Cognito rejects offline_access outright (#1347).
48	  const scope =
49	    scopeOverride ||
50	    ['openid', 'profile', 'email', 'offline_access', apiScope].filter(Boolean).join(' ');
51	
52	  _mgr = new UserManager({
53	    authority,
54	    client_id: clientId,
55	    // Trailing slash matches the registered SPA redirect URI (Azure AD requires a
56	    // trailing slash when the URI has no path segment — see deploy/terraform/azure/sso.tf).
57	    redirect_uri: `${window.location.origin}/`,
58	    post_logout_redirect_uri: `${window.location.origin}/`,
59	    scope,
60	    automaticSilentRenew: true,
61	    userStore: new WebStorageStateStore({ store: window.sessionStorage }),
62	  });
63	  return _mgr;
64	}
65	
66	/** Begin an interactive sign-in (full-page redirect to the IdP). */
67	export async function login(): Promise<void> {
68	  const mgr = getUserManager();
69	  if (mgr) await mgr.signinRedirect();
70	}
71	
72	/** End the session (redirect to the IdP's logout, then back). */
73	export async function logout(): Promise<void> {
74	  const mgr = getUserManager();
75	  if (mgr) await mgr.signoutRedirect();
76	}
77	
78	/**
79	 * True when the current URL is the IdP redirect back. `state` is always present;
80	 * a success carries `code`, a failure (cancelled consent / MFA, denied) carries
81	 * `error` — both must be processed (the error case was a silent no-op before).
82	 */
83	function isSigninRedirect(): boolean {
84	  const params = new URLSearchParams(window.location.search);
85	  return params.has('state') && (params.has('code') || params.has('error'));
86	}
87	
88	/**
89	 * Bootstrap step: if this load is the sign-in redirect back, complete the code
90	 * exchange and scrub the redirect params from the URL (so a reload can't replay
91	 * them). No-op otherwise. Must run before React renders so the first paint is
92	 * post-login. On an IdP error redirect (or a failed exchange), log and fall
93	 * through — AuthGate then shows the sign-in page so the user can retry, rather
94	 * than crashing the app.
95	 */
96	export async function completeSigninIfCallback(): Promise<void> {
97	  const mgr = getUserManager();
98	  if (!mgr || !isSigninRedirect()) return;
99	  try {
100	    await mgr.signinRedirectCallback();
101	  } catch (err) {
102	    console.error('OIDC sign-in did not complete', err);
103	  } finally {
104	    window.history.replaceState({}, document.title, window.location.pathname);
105	  }
106	}
107	
108	let _inflightToken: Promise<string | null> | null = null;
109	
110	/**
111	 * A currently-valid API access token, or null when not signed in. Refreshes
112	 * silently when the cached token is expired; if that needs user interaction
113	 * (expired session / revoked consent / fresh MFA), falls back to an interactive
114	 * redirect and rejects so the in-flight request doesn't fire tokenless — it
115	 * re-issues cleanly once the redirect completes (was #168). Concurrent callers
116	 * share one in-flight acquisition (single-flight), so a dashboard mounting N
117	 * requests at once triggers at most one silent renew / one redirect.
118	 */
119	export function getApiToken(): Promise<string | null> {
120	  if (_inflightToken) return _inflightToken;
121	  _inflightToken = acquireApiToken().finally(() => {
122	    _inflightToken = null;
123	  });
124	  return _inflightToken;
125	}
126	
127	async function acquireApiToken(): Promise<string | null> {
128	  const mgr = getUserManager();
129	  if (!mgr) return null;
130	  const user = await mgr.getUser();
131	  // Not signed in → no token; the request 401s quietly (AuthGate gates the UI).
132	  // Do NOT signinSilent here: with no session it hits the iframe path and, with
133	  // no silent_redirect_uri configured, throws — or worse, redirects mid-request.
134	  if (!user) return null;
135	  if (!user.expired) return user.access_token;
136	  try {
137	    const renewed = await mgr.signinSilent();
