import { ErrorResponse, UserManager, WebStorageStateStore, type User } from 'oidc-client-ts';

import { authConfig, authMode } from './config';

// OAuth error codes from a failed silent renew that genuinely need the user back
// at the IdP (expired session / dead refresh token / fresh consent or MFA) — as
// opposed to a transient network error, which must NOT trigger a redirect (#168).
const INTERACTION_REQUIRED_ERRORS = new Set([
  'login_required',
  'interaction_required',
  'consent_required',
  'account_selection_required',
  'invalid_grant',
]);

/**
 * Generic OIDC auth client (ADR 0028 / #504) — replaces the Azure-specific MSAL
 * client. Any standards-compliant IdP works: Azure AD, Cognito, GCP Identity
 * Platform, Keycloak, or a local dev OIDC — the provider is just the injected
 * `authority`. Authorization-code + PKCE (oidc-client-ts default), refresh-token
 * silent renew (offline_access), session-storage cache (matches the old MSAL
 * choice so a tab reload keeps the session but a closed tab drops it).
 */

let _mgr: UserManager | null = null;

/**
 * The UserManager singleton in real auth mode; null in dev_bypass / unconfigured.
 * Caller awaits nothing to construct it — oidc-client-ts fetches the IdP metadata
 * lazily on first sign-in/callback.
 */
export function getUserManager(): UserManager | null {
  if (authMode !== 'real') return null;
  if (_mgr) return _mgr;

  const { authority, clientId, apiScope, scope: scopeOverride } = authConfig;
  if (!authority || !clientId) {
    // authMode='real' guarantees both are set; defensive guard satisfies the type checker.
    throw new Error(
      'Real auth mode requires an authority + clientId (DATAQ_AUTH_* runtime config)',
    );
  }

  // openid/profile/email → id token; offline_access → refresh token for silent
  // renew; apiScope (when set) makes the access token audience the DataQ API.
  // DATAQ_AUTH_SCOPE replaces the whole string for providers with a different
  // scope vocabulary — Cognito rejects offline_access outright (#1347).
  const scope =
    scopeOverride ||
    ['openid', 'profile', 'email', 'offline_access', apiScope].filter(Boolean).join(' ');

  _mgr = new UserManager({
    authority,
    client_id: clientId,
    // Trailing slash matches the registered SPA redirect URI (Azure AD requires a
    // trailing slash when the URI has no path segment — see deploy/terraform/azure/sso.tf).
    redirect_uri: `${window.location.origin}/`,
    post_logout_redirect_uri: `${window.location.origin}/`,
    scope,
    automaticSilentRenew: true,
    userStore: new WebStorageStateStore({ store: window.sessionStorage }),
  });
  return _mgr;
}

/** Begin an interactive sign-in (full-page redirect to the IdP). */
export async function login(): Promise<void> {
  const mgr = getUserManager();
  if (mgr) await mgr.signinRedirect();
}

/** End the session (redirect to the IdP's logout, then back). */
export async function logout(): Promise<void> {
  const mgr = getUserManager();
  if (mgr) await mgr.signoutRedirect();
}

/**
 * True when the current URL is the IdP redirect back. `state` is always present;
 * a success carries `code`, a failure (cancelled consent / MFA, denied) carries
 * `error` — both must be processed (the error case was a silent no-op before).
 */
function isSigninRedirect(): boolean {
  const params = new URLSearchParams(window.location.search);
  return params.has('state') && (params.has('code') || params.has('error'));
}

/**
 * Bootstrap step: if this load is the sign-in redirect back, complete the code
 * exchange and scrub the redirect params from the URL (so a reload can't replay
 * them). No-op otherwise. Must run before React renders so the first paint is
 * post-login. On an IdP error redirect (or a failed exchange), log and fall
 * through — AuthGate then shows the sign-in page so the user can retry, rather
 * than crashing the app.
 */
export async function completeSigninIfCallback(): Promise<void> {
  const mgr = getUserManager();
  if (!mgr || !isSigninRedirect()) return;
  try {
    await mgr.signinRedirectCallback();
  } catch (err) {
    console.error('OIDC sign-in did not complete', err);
  } finally {
    window.history.replaceState({}, document.title, window.location.pathname);
  }
}

let _inflightToken: Promise<string | null> | null = null;

/**
 * A currently-valid API access token, or null when not signed in. Refreshes
 * silently when the cached token is expired; if that needs user interaction
 * (expired session / revoked consent / fresh MFA), falls back to an interactive
 * redirect and rejects so the in-flight request doesn't fire tokenless — it
 * re-issues cleanly once the redirect completes (was #168). Concurrent callers
 * share one in-flight acquisition (single-flight), so a dashboard mounting N
 * requests at once triggers at most one silent renew / one redirect.
 */
export function getApiToken(): Promise<string | null> {
  if (_inflightToken) return _inflightToken;
  _inflightToken = acquireApiToken().finally(() => {
    _inflightToken = null;
  });
  return _inflightToken;
}

async function acquireApiToken(): Promise<string | null> {
  const mgr = getUserManager();
  if (!mgr) return null;
  const user = await mgr.getUser();
  // Not signed in → no token; the request 401s quietly (AuthGate gates the UI).
  // Do NOT signinSilent here: with no session it hits the iframe path and, with
  // no silent_redirect_uri configured, throws — or worse, redirects mid-request.
  if (!user) return null;
  if (!user.expired) return user.access_token;
  try {
    const renewed = await mgr.signinSilent();
    return renewed?.access_token ?? null;
  } catch (err) {
    // Only hand off to an interactive redirect when the silent renew actually
    // needs the user; transient errors re-throw untouched (no spurious redirect).
    if (err instanceof ErrorResponse && INTERACTION_REQUIRED_ERRORS.has(err.error ?? '')) {
      await mgr.signinRedirect();
    }
    throw err;
  }
}

/** Test-only: drop the cached UserManager so the next call rebuilds it. */
export function resetAuthClientCache(): void {
  _mgr = null;
}

export type { User };

/**
 * Auth configuration — sourced at RUNTIME, not build time (ADR 0028).
 *
 * The container serves `/config.js` (rendered from env by nginx at startup) which
 * sets `window.__DATAQ_CONFIG__` before the app bundle runs. That means one
 * generic image with nothing baked in — no cloud, no secret, no auth-bypass.
 * When no such global is present — `pnpm dev`, and the static/SWA build until the
 * ADR-0028 cutover — we fall back to the build-time `VITE_*` env (bypass there
 * stays DEV-gated, so a production static bundle can't enable it).
 *
 * The injected contract is provider-neutral (`DATAQ_AUTH_*`): `mode` + a standard
 * OIDC-shaped `authority` / `clientId` / `apiScope`. Azure is one populated shape
 * (`authority = https://login.microsoftonline.com/<tenant>/v2.0`); no `AZURE` in
 * the contract.
 *
 * Mode is computed once at module load:
 * - 'real'         — `mode:'oidc'` with authority + clientId present. The generic
 *                    OIDC auth client (oidc-client-ts — ADR 0028/#504) drives
 *                    redirect-flow login + token acquisition.
 * - 'otp'          — ONLY when `mode:'otp'` is explicitly set (ADR 0032). Email
 *                    one-time codes; the credential is an HttpOnly cookie the SPA
 *                    never sees, so there is nothing else to configure here.
 * - 'dev_bypass'   — ONLY when `mode:'bypass'` is explicitly set. Fail-closed:
 *                    never inferred from missing config. Renders a fixed dev user.
 * - 'unconfigured' — anything else. AuthGate shows a setup-needed banner.
 *
 * The `otp` value is one half of a **pair of coordinated selectors** (ADR 0032
 * decision 2): the backend infers its own mode from `AUTH_EMAIL_*` + the signup
 * allowlist and never reads this one. Set both or neither — this alone yields a
 * code form whose endpoints 503.
 */

export type AuthMode = 'real' | 'otp' | 'dev_bypass' | 'unconfigured';

/** The runtime auth contract injected via `window.__DATAQ_CONFIG__.auth`. */
export interface DataqAuthConfig {
  /**
   * 'bypass' = no IdP (local/eval); 'otp' = email one-time codes (ADR 0032);
   * 'oidc' = IdP sign-in. Absent/unrecognised → unconfigured.
   */
  mode?: 'bypass' | 'otp' | 'oidc';
  /** OIDC issuer/authority URL (e.g. https://login.microsoftonline.com/<tenant>/v2.0). */
  authority?: string;
  /** The public SPA client id registered with the IdP. */
  clientId?: string;
  /** Full scope string requested for the API access token (Azure: api://<api-client-id>/<scope>). */
  apiScope?: string;
  /**
   * Complete OVERRIDE of the requested OAuth scope string (#1347). When set, it
   * replaces the default `openid profile email offline_access [apiScope]`
   * entirely. Needed because scope support is provider-specific: AWS Cognito
   * rejects `offline_access` (`error=invalid_scope` — not one of its system
   * scopes), so a Cognito deployment sets e.g. "openid email profile" here
   * (Cognito issues refresh tokens on the code grant regardless).
   */
  scope?: string;
}

declare global {
  interface Window {
    __DATAQ_CONFIG__?: { auth?: DataqAuthConfig };
  }
}

/**
 * Build-time fallback for `pnpm dev` (no injected /config.js). Maps the legacy
 * VITE_* Azure vars onto the generic contract so local dev is unchanged. Bypass
 * still requires the explicit VITE_AUTH_DEV_BYPASS=true opt-in.
 */
function fromBuildEnv(): DataqAuthConfig {
  const tenantId = import.meta.env.VITE_AZURE_TENANT_ID;
  const clientId = import.meta.env.VITE_AZURE_SPA_CLIENT_ID;
  const apiClientId = import.meta.env.VITE_AZURE_API_CLIENT_ID;
  const scope = import.meta.env.VITE_AZURE_API_SCOPE || 'user_impersonation';
  // Belt-and-suspenders: bypass in the build-env fallback stays gated on a DEV
  // build, so a production static bundle (e.g. the SWA deploy, which serves this
  // fallback path — the /config.js stub sets no global) can never enable auth
  // bypass even if VITE_AUTH_DEV_BYPASS=true were baked in. The image path never
  // reaches here (nginx injects window.__DATAQ_CONFIG__).
  const bypass = import.meta.env.DEV && import.meta.env.VITE_AUTH_DEV_BYPASS === 'true';
  // `pnpm dev` against a locally-running OTP backend. Explicit opt-in only — an
  // unrecognised value falls through to the OIDC/unconfigured branches rather
  // than being coerced into a mode. Not DEV-gated like bypass, because unlike
  // bypass this mode *is* a real authenticator: turning it on in a production
  // bundle grants nothing without a mailbox and a server-side allowlist.
  const otp = import.meta.env.VITE_AUTH_MODE === 'otp';
  return {
    // OTP is checked BEFORE bypass (#1150). `VITE_AUTH_DEV_BYPASS=true` is the
    // long-standing dev default and lives in the compose file; an explicitly
    // named mode has to win over a leftover boolean, or the local stack would
    // render "no sign-in at all" while its backend was serving email codes —
    // the split-brain the two-selector contract exists to prevent. Safe
    // direction: this can only ever REPLACE a bypass with a real authenticator.
    mode: otp ? 'otp' : bypass ? 'bypass' : tenantId && clientId ? 'oidc' : undefined,
    authority: tenantId ? `https://login.microsoftonline.com/${tenantId}/v2.0` : undefined,
    clientId: clientId || undefined,
    apiScope: apiClientId ? `api://${apiClientId}/${scope}` : undefined,
  };
}

// The injected runtime config wins; the build-time env is the dev-only fallback
// used only when no /config.js was served (i.e. `pnpm dev`).
const injected = typeof window !== 'undefined' ? window.__DATAQ_CONFIG__?.auth : undefined;
const cfg: DataqAuthConfig = injected ?? fromBuildEnv();

export const authConfig = {
  authority: cfg.authority,
  clientId: cfg.clientId,
  apiScope: cfg.apiScope,
  scope: cfg.scope,
} as const;

export const authMode: AuthMode = (() => {
  // Fail-closed: bypass and otp ONLY on their explicit flag, never inferred.
  if (cfg.mode === 'bypass') return 'dev_bypass';
  // Checked before the OIDC branch so a deployment that leaves stale
  // authority/clientId values behind while switching to `otp` gets the mode it
  // asked for, rather than silently continuing to render an IdP redirect.
  if (cfg.mode === 'otp') return 'otp';
  if (cfg.authority && cfg.clientId) return 'real';
  return 'unconfigured';
})();

/** Human-readable auth-method label per mode (Profile + Settings "Authentication" rows). */
export const AUTH_METHOD_LABELS: Record<AuthMode, string> = {
  real: 'OIDC (SSO)',
  otp: 'Email one-time code',
  dev_bypass: 'Dev bypass (no IdP)',
  unconfigured: 'Not configured',
};

/** The label for the mode this deployment is actually running in. */
export const authMethodLabel = AUTH_METHOD_LABELS[authMode];

export const DEV_USER = {
  name: 'Dev Bypass User',
  username: 'dev-bypass@dataq.local',
  homeAccountId: 'dev-bypass',
  isDev: true as const,
};

