78	/**
79	 * True when the current URL is the IdP redirect back. `state` is always present;
80	 * a success carries `code`, a failure (cancelled consent / MFA, denied) carries
81	 * `error` — both must be processed (the error case was a silent no-op before).
82	 */
83	function isSigninRedirect(): boolean {
84	  const params = new URLSearchParams(window.location.search);
85	  return params.has('state') && (params.has('code') || params.has('error'));
86	}
