108	let _inflightToken: Promise<string | null> | null = null;
109	
110	/**
111	 * A currently-valid API access token, or null when not signed in. Refreshes
112	 * silently when the cached token is expired; if that needs user interaction
113	 * (expired session / revoked consent / fresh MFA), falls back to an interactive
114	 * redirect and rejects so the in-flight request doesn't fire tokenless — it
115	 * re-issues cleanly once the redirect completes (was #168). Concurrent callers
116	 * share one in-flight acquisition (single-flight), so a dashboard mounting N
117	 * requests at once triggers at most one silent renew / one redirect.
118	 */
