async () => {
  await new Promise(r => setTimeout(r, 3000)); // let the code exchange finish
  let bearer = '';
  for (let i = 0; i < sessionStorage.length; i++) {
    const k = sessionStorage.key(i);
    if (k.startsWith('oidc.user:')) bearer = JSON.parse(sessionStorage.getItem(k)).access_token;
  }
  if (!bearer) return 'NO BEARER';
  // mint a PAT — value kept in window state only
  const created = await fetch('/api/v1/me/api-keys', {
    method: 'POST',
    headers: { Authorization: 'Bearer ' + bearer, 'Content-Type': 'application/json' },
    body: JSON.stringify({ name: 'mcp-e2e-test' }),
  }).then(r => r.json());
  if (!created.token) return { patCreateFailed: created };
  window.__pat = created.token;
  window.__patId = created.id;
  // MCP initialize
  const init = await fetch('/mcp/', {
    method: 'POST',
    headers: {
      Authorization: 'Bearer ' + window.__pat,
      'Content-Type': 'application/json',
      Accept: 'application/json, text/event-stream',
    },
    body: JSON.stringify({ jsonrpc: '2.0', id: 1, method: 'initialize', params: {
      protocolVersion: '2025-03-26', capabilities: {}, clientInfo: { name: 'e2e', version: '1' } } }),
  });
  window.__sid = init.headers.get('mcp-session-id');
  const initBody = await init.text();
  return { status: init.status, sid: !!window.__sid, serverInfo: (initBody.match(/"serverInfo":\{[^}]*\}/) || ['?'])[0] };
}

